// Code «Calcular periodo» · Run Once for All Items
// Llega un item de «Elegir mes» (con `mes`) o de «Día 1 a las 8:00» (sin `mes`).
// Devuelve un item { desde, hasta, nombre_mes }.

const ZONA = 'Europe/Madrid';
const MESES = ['enero', 'febrero', 'marzo', 'abril', 'mayo', 'junio',
  'julio', 'agosto', 'septiembre', 'octubre', 'noviembre', 'diciembre'];

const mes = $input.first().json.mes;
let dia;
if (mes) {
  // El campo Date del formulario llega como `yyyy-MM-dd`
  dia = DateTime.fromISO(String(mes).slice(0, 10), { zone: ZONA });
  if (!dia.isValid) throw new Error(`Calcular periodo: la fecha del formulario no es válida: «${mes}»`);
} else {
  // Programado: el mes anterior a hoy
  dia = DateTime.now().setZone(ZONA).minus({ months: 1 });
}

const inicio = dia.startOf('month');
const fin = dia.endOf('month');

return [{ json: {
  desde: inicio.toFormat('yyyy-MM-dd'),
  hasta: fin.toFormat('yyyy-MM-dd'),
  nombre_mes: `${MESES[inicio.month - 1]} de ${inicio.year}`,
} }];

// Code «Preparar informe» · Run Once for All Items
// Lee el periodo y las cuatro listas de la API, calcula las cifras del mes y
// devuelve un item { asunto, html }. No recalcula `pendiente`: suma el que da la app.

const ZONA = 'Europe/Madrid';
const FORMAS = ['efectivo', 'tarjeta', 'bizum'];
const { desde, hasta, nombre_mes } = $('Calcular periodo').first().json;

// Items de un GET sin el item vacío de Always Output Data (no tiene `id`)
const leer = nombre => $(nombre).all().map(i => i.json).filter(j => j && j.id != null);

const ventas = leer('Leer ventas del mes');
const abonosDesde = leer('Leer abonos desde el día 1');
const apartados = leer('Leer apartados');
const vales = leer('Leer vales');

const enMes = fecha => fecha >= desde && fecha <= hasta;
const abonosMes = abonosDesde.filter(b => enMes(b.fecha));

// Importes en céntimos para sumar sin decimales raros
const cent = x => Math.round(Number(x) * 100);
const eur = c => (c / 100).toFixed(2);
const fecha = f => (f ? f.split('-').reverse().join('/') : '');
const esc = t => String(t ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

// Suma total y por forma de pago
function sumar(lista) {
  const r = { n: lista.length, total: 0 };
  for (const f of FORMAS) r[f] = 0;
  for (const x of lista) {
    const c = cent(x.importe);
    r.total += c;
    if (FORMAS.includes(x.forma_pago)) r[x.forma_pago] += c;
  }
  return r;
}
const sv = sumar(ventas);
const sa = sumar(abonosMes);
const st = { n: sv.n + sa.n, total: sv.total + sa.total };
for (const f of FORMAS) st[f] = sv[f] + sa[f];

// Pendiente de cobro: el `pendiente` de la app de los apartados activos
const activos = apartados.filter(a => a.estado === 'activo');
const pendiente = activos.reduce((s, a) => s + cent(a.pendiente), 0);
const ahora = DateTime.now().setZone(ZONA).toFormat('dd/MM/yyyy HH:mm');

// Nuevos: fecha del apartado dentro del mes
const porFechaId = (a, b) => (a.fecha < b.fecha ? -1 : a.fecha > b.fecha ? 1 : a.id - b.id);
const nuevos = apartados.filter(a => enMes(a.fecha)).sort(porFechaId);

// Liquidados: estado liquidado y su último abono dentro del mes
const ultimoAbono = {};
for (const b of abonosDesde) {
  if (!ultimoAbono[b.apartado_id] || b.fecha > ultimoAbono[b.apartado_id]) ultimoAbono[b.apartado_id] = b.fecha;
}
const liquidados = apartados
  .filter(a => a.estado === 'liquidado' && ultimoAbono[a.id] && enMes(ultimoAbono[a.id]))
  .map(a => ({ ...a, ultimo: ultimoAbono[a.id] }))
  .sort((a, b) => (a.ultimo < b.ultimo ? -1 : a.ultimo > b.ultimo ? 1 : a.id - b.id));

// Vencidos: fecha del vale dentro del mes
const apartadoPorId = Object.fromEntries(apartados.map(a => [a.id, a]));
const vencidos = vales.filter(v => enMes(v.fecha)).sort(porFechaId)
  .map(v => ({ vale: v, apartado: apartadoPorId[v.apartado_id] ?? { id: v.apartado_id } }));

const sinMovimientos = !ventas.length && !abonosMes.length && !nuevos.length && !liquidados.length && !vencidos.length;

// --- HTML con estilos en línea ---
const TD = 'border:1px solid #ccc;padding:6px 8px;';
const celda = (t, num) => `<td style="${TD}${num ? 'text-align:right;white-space:nowrap;' : ''}">${t}</td>`;
const cab = t => `<th style="${TD}background:#f2f2f2;text-align:left;">${t}</th>`;
const tabla = (cabeceras, filas) =>
  `<div style="overflow-x:auto;"><table style="border-collapse:collapse;font-size:14px;margin:4px 0 16px;">`
  + `<tr>${cabeceras.map(cab).join('')}</tr>${filas.join('')}</table></div>`;
const titulo = t => `<h3 style="margin:20px 0 6px;font-size:16px;">${t}</h3>`;
const ninguno = '<p style="margin:4px 0 16px;color:#666;">Ninguno.</p>';

const filaRecaudacion = (nombre, s, negrita) => {
  const b = t => (negrita ? `<b>${t}</b>` : t);
  return `<tr>${celda(b(nombre))}${FORMAS.map(f => celda(b(eur(s[f])), true)).join('')}`
    + `${celda(b(eur(s.total)), true)}${celda(b(s.n), true)}</tr>`;
};

const partes = [];
partes.push(`<h2 style="margin:0 0 4px;font-size:20px;">Informe de ${esc(nombre_mes)}</h2>`);
partes.push(`<p style="margin:0 0 12px;color:#666;">Del ${fecha(desde)} al ${fecha(hasta)}</p>`);
if (sinMovimientos) {
  partes.push(`<p style="margin:0 0 12px;padding:8px;background:#fff6d6;">No hubo movimientos en ${esc(nombre_mes)}.</p>`);
}

partes.push(titulo('Recaudación (€)'));
partes.push(tabla(['', 'Efectivo', 'Tarjeta', 'Bizum', 'Total', 'Nº'], [
  filaRecaudacion('Ventas directas', sv),
  filaRecaudacion('Abonos', sa),
  filaRecaudacion('Total recaudado', st, true),
]));
partes.push('<p style="margin:-10px 0 16px;font-size:12px;color:#666;">Los abonos incluyen los abonos iniciales de los apartados.</p>');

partes.push(titulo('Pendiente de cobro'));
partes.push(`<p style="margin:4px 0 16px;"><b>${eur(pendiente)} €</b> en ${activos.length} apartados activos `
  + `<span style="color:#666;">(a ${ahora})</span></p>`);

partes.push(titulo(`Apartados nuevos: ${nuevos.length}`));
partes.push(nuevos.length ? tabla(['Nº', 'Fecha', 'Cliente', 'Producto', 'Talla', 'Precio', 'Estado'],
  nuevos.map(a => `<tr>${celda(a.id, true)}${celda(fecha(a.fecha))}${celda(esc(a.cliente))}${celda(esc(a.producto))}`
    + `${celda(esc(a.talla))}${celda(eur(cent(a.precio)), true)}${celda(esc(a.estado))}</tr>`)) : ninguno);

partes.push(titulo(`Apartados liquidados: ${liquidados.length}`));
partes.push(liquidados.length ? tabla(['Nº', 'Cliente', 'Producto', 'Precio', 'Último abono'],
  liquidados.map(a => `<tr>${celda(a.id, true)}${celda(esc(a.cliente))}${celda(esc(a.producto))}`
    + `${celda(eur(cent(a.precio)), true)}${celda(fecha(a.ultimo))}</tr>`)) : ninguno);

partes.push(titulo(`Apartados vencidos: ${vencidos.length}`));
partes.push(vencidos.length ? tabla(['Nº', 'Cliente', 'Producto', 'Fecha límite', 'Vale', 'Importe'],
  vencidos.map(({ vale: v, apartado: a }) => `<tr>${celda(a.id, true)}${celda(esc(a.cliente))}${celda(esc(a.producto))}`
    + `${celda(fecha(a.fecha_limite))}${celda(esc(v.codigo))}${celda(eur(cent(v.importe)), true)}</tr>`)) : ninguno);

const html = `<div style="font-family:Arial,Helvetica,sans-serif;color:#222;max-width:680px;">${partes.join('\n')}</div>`;

return [{ json: {
  asunto: `Informe de ${nombre_mes}: ${eur(st.total)} € recaudados`,
  html,
} }];
